css:
@import url("https://fonts.googleapis.com/css2?family=Jost:wght@300..700&display=swap");

ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

.nifty-part-header-2 .bt-header {--navy:#004877;--ink:#252627;--cream:#fff;--sand:#F3E9D9;--sky:#3C96E7;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.62);--body:rgba(37,38,39,.78);--serif:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);--ann:40px;--bar:84px;position:sticky;top:calc(var(--ann) * -1);z-index:900;font-family:var(--sans);font-size:16px;line-height:1.5;color:var(--ink);background:var(--cream);-webkit-font-smoothing:antialiased;text-align:left}
.nifty-part-header-2 .bt-header *, .nifty-part-header-2 .bt-header *::before, .nifty-part-header-2 .bt-header *::after {box-sizing:border-box}
.nifty-part-header-2 .bt-header a {color:inherit;text-decoration:none}
.nifty-part-header-2 .bt-header ul {list-style:none;margin:0;padding:0}
.nifty-part-header-2 .bt-header p {margin:0}
.nifty-part-header-2 .bt-header img {display:block;max-width:100%}
.nifty-part-header-2 .bt-header svg {width:20px;height:20px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.nifty-part-header-2 .bt-header [hidden] {display:none!important}
.nifty-part-header-2 .bt-header a:focus-visible, .nifty-part-header-2 .bt-header label:focus-visible, .nifty-part-header-2 .bt-header button:focus-visible, .nifty-part-header-2 .bt-header input:focus-visible {outline:2px solid var(--sky);outline-offset:3px}
.nifty-part-header-2 .bt-header .bt-skip {position:absolute;left:12px;top:calc(var(--ann) + 12px);z-index:60;background:var(--navy);color:#fff;padding:12px 18px;font-size:13px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;opacity:0;pointer-events:none;clip-path:inset(50%)}
.nifty-part-header-2 .bt-header .bt-skip:focus {opacity:1;pointer-events:auto;clip-path:none}
.nifty-part-header-2 .bt-header .bt-announce {height:var(--ann);background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap;overflow:hidden}
.nifty-part-header-2 .bt-header .bt-ann-track {display:flex;align-items:center}
.nifty-part-header-2 .bt-header .bt-ann-set {display:flex;align-items:center;flex:none}
.nifty-part-header-2 .bt-header .bt-ann-set+.bt-ann-set {display:none}
.nifty-part-header-2 .bt-header .bt-ann-set>span {padding:0 22px;position:relative}
.nifty-part-header-2 .bt-header .bt-ann-set>span+span::before {content:"";position:absolute;left:0;top:50%;width:1px;height:12px;background:rgba(255,255,255,.4);transform:translateY(-50%)}
.nifty-part-header-2 .bt-header .bt-ann-sale {display:inline-flex;align-items:center;gap:9px;height:26px;margin-left:10px;padding:0 14px 0 12px;border-radius:999px;background:var(--cream);color:var(--navy);letter-spacing:.14em;transition:background .4s var(--ease),transform .5s var(--ease)}
.nifty-part-header-2 .bt-header .bt-ann-sale:hover {background:#fff;transform:translateY(-1px)}
.nifty-part-header-2 .bt-header .bt-ann-sale b {font-weight:500;padding-left:9px;border-left:1px solid rgba(0,72,119,.32)}
.nifty-part-header-2 .bt-header .bt-ann-sale i {width:7px;height:7px;background:var(--navy);transform:rotate(45deg);animation:btAnnPulse 2.4s ease-in-out infinite}
@keyframes btAnnPulse {0%,100%{box-shadow:0 0 0 0 rgba(0,72,119,.5)}60%{box-shadow:0 0 0 7px rgba(0,72,119,0)}}
@keyframes btAnnRun {to{transform:translateX(-50%)}}
.nifty-part-header-2 .bt-header .bt-bar {position:relative;display:flex;align-items:center;gap:clamp(16px,2vw,32px);height:var(--bar);padding:0 var(--gut);background:var(--cream);border-bottom:1px solid var(--line)}
.nifty-part-header-2 .bt-header .bt-toggle {position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.nifty-part-header-2 .bt-header .bt-nav-toggle, .nifty-part-header-2 .bt-header .bt-sub {display:none}
.nifty-part-header-2 .bt-header .bt-search-toggle:focus-visible~.bt-actions .bt-act-search, .nifty-part-header-2 .bt-header .bt-nav-toggle:focus-visible~.bt-actions .bt-burger, .nifty-part-header-2 .bt-header .bt-sub:focus-visible~.bt-sub-lbl {outline:2px solid var(--sky);outline-offset:3px}
.nifty-part-header-2 .bt-header .bt-logo {flex-shrink:0;display:block}
.nifty-part-header-2 .bt-header .bt-logo img {height:26px;width:auto}
.nifty-part-header-2 .bt-header .bt-nav {flex:1;display:flex;justify-content:center;align-self:stretch;min-width:0}
.nifty-part-header-2 .bt-header .bt-nav-head, .nifty-part-header-2 .bt-header .bt-nav-foot, .nifty-part-header-2 .bt-header .bt-sub-lbl, .nifty-part-header-2 .bt-header .bt-act.bt-burger {display:none}
.nifty-part-header-2 .bt-header .bt-menu {display:flex;align-items:stretch;gap:clamp(12px,1.55vw,28px)}
.nifty-part-header-2 .bt-header .bt-item {display:flex;align-items:stretch}
.nifty-part-header-2 .bt-header .bt-item>a {display:flex;align-items:center;position:relative;font-size:12.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap;transition:color .4s var(--ease)}
.nifty-part-header-2 .bt-header .bt-item>a::after {content:"";position:absolute;left:0;right:0;bottom:26px;height:1px;background:var(--navy);transform:scaleX(0);transform-origin:left;transition:transform .6s var(--ease)}
.nifty-part-header-2 .bt-header .bt-item:hover>a, .nifty-part-header-2 .bt-header .bt-item:focus-within>a {color:var(--navy)}
.nifty-part-header-2 .bt-header .bt-item:hover>a::after, .nifty-part-header-2 .bt-header .bt-item:focus-within>a::after {transform:scaleX(1)}
.nifty-part-header-2 .bt-header .bt-item-special>a {align-self:center;position:relative;overflow:hidden;height:42px;padding:0 18px 0 16px;color:#fff;background:linear-gradient(135deg,#004877 0%,#00365b 60%,#001f36 100%);box-shadow:0 14px 22px -14px rgba(0,54,91,.9);transition:transform .6s var(--ease),box-shadow .6s var(--ease)}
.nifty-part-header-2 .bt-header .bt-item-special>a::before {content:"";width:7px;height:7px;flex:none;background:var(--pale,#AED3F5);transform:rotate(45deg);margin-right:10px;animation:btNavGem 3.2s var(--ease) infinite}
.nifty-part-header-2 .bt-header .bt-item-special>a::after {left:-60%;right:auto;top:0;bottom:0;width:46%;height:auto;background:linear-gradient(100deg,transparent,rgba(255,255,255,.34),transparent);transform:skewX(-18deg);animation:btNavSheen 4.6s ease-in-out infinite}
.nifty-part-header-2 .bt-header .bt-item-special:hover>a, .nifty-part-header-2 .bt-header .bt-item-special:focus-within>a {color:#fff;transform:translateY(-2px);box-shadow:0 20px 26px -14px rgba(0,54,91,1)}
.nifty-part-header-2 .bt-header .bt-item-special:hover>a::after, .nifty-part-header-2 .bt-header .bt-item-special:focus-within>a::after {transform:skewX(-18deg)}
@keyframes btNavSheen {0%,58%{left:-60%}100%{left:130%}}
@keyframes btNavGem {0%,100%{transform:rotate(45deg) scale(1)}50%{transform:rotate(225deg) scale(1.15)}}
@media (prefers-reduced-motion:reduce) {.nifty-part-header-2 .bt-header .bt-item-special>a::before, .nifty-part-header-2 .bt-header .bt-item-special>a::after {animation:none}}
.nifty-part-header-2 .bt-header .bt-mega {position:absolute;left:0;right:0;top:100%;z-index:5;background:var(--cream);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:-1px;padding:44px var(--gut) 52px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity .4s var(--ease),transform .4s var(--ease),visibility 0s .4s}
.nifty-part-header-2 .bt-header .bt-item:hover>.bt-mega, .nifty-part-header-2 .bt-header .bt-item:focus-within>.bt-mega {opacity:1;visibility:visible;transform:none;transition-delay:.05s,.05s,0s}
.nifty-part-header-2 .bt-header .bt-mega-in {max-width:1320px;margin:0 auto;display:flex;gap:clamp(32px,4vw,72px)}
.nifty-part-header-2 .bt-header .bt-mega-col {flex:1;min-width:0}
.nifty-part-header-2 .bt-header .bt-mega-col-2 ul {columns:2;column-gap:40px}
.nifty-part-header-2 .bt-header .bt-mega-h {font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin:0 0 16px;padding-bottom:14px;border-bottom:1px solid var(--line2)}
.nifty-part-header-2 .bt-header .bt-mega li {break-inside:avoid}
.nifty-part-header-2 .bt-header .bt-mega li a {display:inline-block;font-family:var(--serif);font-weight:500;font-size:20px;line-height:1.3;padding:6px 0;transition:color .3s var(--ease),transform .5s var(--ease)}
.nifty-part-header-2 .bt-header .bt-mega li a:hover {color:var(--navy);transform:translateX(6px)}
.nifty-part-header-2 .bt-header .bt-mega-all {display:inline-flex;align-items:center;gap:10px;margin-top:22px;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--navy);border-bottom:1px solid currentColor;padding-bottom:5px}
.nifty-part-header-2 .bt-header .bt-mega-all svg {width:14px;height:14px}
.nifty-part-header-2 .bt-header .bt-mega-card {flex:1.25;max-width:380px;margin-left:auto;display:block}
.nifty-part-header-2 .bt-header .bt-mega-card span.bt-mega-img {display:block;aspect-ratio:4/3;overflow:hidden;background:var(--sand)}
.nifty-part-header-2 .bt-header .bt-mega-card img {width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ease)}
.nifty-part-header-2 .bt-header .bt-mega-card:hover img {transform:scale(1.05)}
.nifty-part-header-2 .bt-header .bt-mega-card b {display:block;font-family:var(--serif);font-weight:500;font-size:22px;margin-top:16px}
.nifty-part-header-2 .bt-header .bt-mega-card small {display:block;font-size:13.5px;color:var(--body);margin-top:4px}
.nifty-part-header-2 .bt-header .bt-mega-bt {flex:3.4}
.nifty-part-header-2 .bt-header .bt-mega .bt-btgrid {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px 26px}
.nifty-part-header-2 .bt-header .bt-mega .bt-btgrid a {display:flex;align-items:center;gap:14px;padding:0;font-family:var(--sans);font-size:13px;min-width:0}
.nifty-part-header-2 .bt-header .bt-mega .bt-btgrid a:hover {transform:none}
.nifty-part-header-2 .bt-header .bt-btgrid img {width:60px;height:60px;flex:none;object-fit:cover;border:1px solid var(--line);transition:transform .6s var(--ease),box-shadow .6s var(--ease)}
.nifty-part-header-2 .bt-header .bt-btgrid a:hover img {transform:perspective(300px) rotateY(-16deg) scale(1.06);box-shadow:10px 10px 22px -12px rgba(0,29,51,.5)}
.nifty-part-header-2 .bt-header .bt-btgrid span {min-width:0}
.nifty-part-header-2 .bt-header .bt-btgrid b {display:block;font-family:var(--serif);font-weight:500;font-size:18px;line-height:1.15}
.nifty-part-header-2 .bt-header .bt-btgrid small {display:block;font-size:12px;color:var(--mut);margin-top:3px}
.nifty-part-header-2 .bt-header .bt-mega-sale {flex:1;min-width:230px;max-width:300px;margin-left:auto;display:flex;flex-direction:column;justify-content:flex-end;padding:26px 26px 24px;background:linear-gradient(160deg,#004877,#001d33);color:#fff;position:relative;overflow:hidden}
.nifty-part-header-2 .bt-header .bt-mega-sale::before {content:"12";position:absolute;right:-8px;top:-34px;font-family:var(--serif);font-weight:500;font-size:190px;line-height:1;color:rgba(174,211,245,.14)}
.nifty-part-header-2 .bt-header .bt-mega-sale small {position:relative;font-size:10.5px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:#AED3F5}
.nifty-part-header-2 .bt-header .bt-mega-sale b {position:relative;font-family:var(--serif);font-weight:500;font-size:30px;line-height:1.05;margin:8px 0 6px}
.nifty-part-header-2 .bt-header .bt-mega-sale span {position:relative;font-family:var(--serif);font-weight:500;font-style:normal;font-size:18px;color:#AED3F5}
.nifty-part-header-2 .bt-header .bt-mega-sale em {position:relative;display:inline-flex;align-items:center;gap:10px;margin-top:20px;font-style:normal;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;transition:gap .5s var(--ease)}
.nifty-part-header-2 .bt-header .bt-mega-sale em svg {width:14px;height:14px}
.nifty-part-header-2 .bt-header .bt-mega-sale:hover em {gap:16px}
.nifty-part-header-2 .bt-header .bt-brief-tab {position:fixed;right:0;top:50%;z-index:8;display:flex;flex-direction:column;align-items:center;gap:14px;width:46px;padding:16px 0 18px;margin-top:-104px;background:linear-gradient(180deg,#004877 0%,#002a47 100%);color:#fff;cursor:pointer;border-radius:8px 0 0 8px;box-shadow:-12px 16px 36px -16px rgba(0,29,51,.7);transition:width .5s var(--ease),box-shadow .5s var(--ease);overflow:hidden}
.nifty-part-header-2 .bt-header .bt-brief-tab::after {content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,0) 30%,rgba(174,211,245,.34) 50%,rgba(255,255,255,0) 70%);background-size:100% 300%;animation:btBriefSheen 4.6s ease-in-out infinite;pointer-events:none}
.nifty-part-header-2 .bt-header .bt-brief-tab:hover {width:54px;box-shadow:-18px 18px 44px -14px rgba(0,29,51,.8)}
.nifty-part-header-2 .bt-header .bt-brief-gem {width:15px;height:15px;background:linear-gradient(135deg,#fff 0%,#AED3F5 100%);animation:btBriefGem 3.8s linear infinite}
.nifty-part-header-2 .bt-header .bt-brief-tab span {writing-mode:vertical-rl;transform:rotate(180deg);font-size:11px;font-weight:500;letter-spacing:.26em;text-transform:uppercase;white-space:nowrap}
@keyframes btBriefGem {from{transform:perspective(90px) rotateY(0deg) rotate(45deg)}to{transform:perspective(90px) rotateY(360deg) rotate(45deg)}}
@keyframes btBriefSheen {0%,55%{background-position:0 130%}100%{background-position:0 -130%}}
.nifty-part-header-2 .bt-header .bt-brief-scrim {position:fixed;inset:0;z-index:44;background:rgba(0,20,36,.64);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);opacity:0;visibility:hidden;cursor:pointer;transition:opacity .6s var(--ease),visibility 0s .6s}
.nifty-part-header-2 .bt-header .bt-brief-toggle:checked~.bt-brief-scrim {opacity:1;visibility:visible;transition-delay:0s}
.nifty-part-header-2 .bt-header .bt-brief-panel {position:fixed;top:0;right:0;bottom:0;z-index:45;width:min(520px,100vw);display:flex;flex-direction:column;color:#fff;background:linear-gradient(168deg,#004877 0%,#00365b 44%,#001a2e 100%);overflow:hidden;visibility:hidden;pointer-events:none;clip-path:inset(0 0 0 100%);transform-origin:100% 50%;transform:perspective(1500px) rotateY(-34deg);transition:clip-path .85s var(--ease),transform .95s var(--ease),visibility 0s .95s}
.nifty-part-header-2 .bt-header .bt-brief-toggle:checked~.bt-brief-panel {clip-path:inset(0);transform:perspective(1500px) rotateY(0deg);visibility:visible;pointer-events:auto;transition-delay:0s}
.nifty-part-header-2 .bt-header .bt-brief-floor {position:absolute;left:0;right:0;bottom:0;height:210px;overflow:hidden;perspective:340px;perspective-origin:50% 0;pointer-events:none;opacity:.55;-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 70%);mask-image:linear-gradient(180deg,transparent 0,#000 70%)}
.nifty-part-header-2 .bt-header .bt-brief-floor i {position:absolute;left:-120%;right:-120%;top:0;height:900px;transform-origin:50% 0;transform:translateZ(-300px) rotateX(76deg);background-image:linear-gradient(rgba(174,211,245,.42) 1.5px,transparent 1.5px),linear-gradient(90deg,rgba(174,211,245,.42) 1.5px,transparent 1.5px);background-size:74px 74px;animation:btBriefFloor 18s linear infinite}
@keyframes btBriefFloor {to{background-position:0 148px}}
.nifty-part-header-2 .bt-header .bt-bs {display:none}
.nifty-part-header-2 .bt-header .bt-bf {position:relative;z-index:1;display:flex;flex-direction:column;flex:1;min-height:0;margin:0}
.nifty-part-header-2 .bt-header .bt-bf-head {display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:30px 22px 0 34px}
.nifty-part-header-2 .bt-header .bt-bf-k {font-size:11px;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:#AED3F5}
.nifty-part-header-2 .bt-header .bt-bf-t {font-family:var(--serif);font-weight:500;font-size:clamp(34px,4.4vw,44px);line-height:1;margin-top:10px}
.nifty-part-header-2 .bt-header .bt-bf-t em {font-style:normal;color:#AED3F5}
.nifty-part-header-2 .bt-header .bt-brief-panel .bt-x {color:#fff;flex:none;margin-top:-6px}
.nifty-part-header-2 .bt-header .bt-brief-panel .bt-x:hover {color:#AED3F5}
.nifty-part-header-2 .bt-header .bt-bf-prog {display:flex;align-items:center;gap:9px;padding:22px 34px 0}
.nifty-part-header-2 .bt-header .bt-bf-prog i {width:22px;height:22px;border:1px solid rgba(174,211,245,.5);transition:transform .9s var(--ease),background .6s var(--ease),border-color .6s var(--ease)}
.nifty-part-header-2 .bt-header .bt-bf-prog p {margin-left:auto;font-size:11px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.72);display:none}
.nifty-part-header-2 .bt-header .bt-bs1:checked~.bt-bf .bt-bf-prog i:nth-of-type(-n+1), .nifty-part-header-2 .bt-header .bt-bs2:checked~.bt-bf .bt-bf-prog i:nth-of-type(-n+2), .nifty-part-header-2 .bt-header .bt-bs3:checked~.bt-bf .bt-bf-prog i:nth-of-type(-n+3), .nifty-part-header-2 .bt-header .bt-bs4:checked~.bt-bf .bt-bf-prog i:nth-of-type(-n+4) {background:var(--cream);border-color:var(--cream);transform:perspective(120px) rotateY(180deg)}
.nifty-part-header-2 .bt-header .bt-bs1:checked~.bt-bf .bt-bf-c1, .nifty-part-header-2 .bt-header .bt-bs2:checked~.bt-bf .bt-bf-c2, .nifty-part-header-2 .bt-header .bt-bs3:checked~.bt-bf .bt-bf-c3, .nifty-part-header-2 .bt-header .bt-bs4:checked~.bt-bf .bt-bf-c4 {display:block}
.nifty-part-header-2 .bt-header .bt-bf-body {flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:26px 34px 10px}
.nifty-part-header-2 .bt-header .bt-step {display:none;border:0;margin:0;padding:0;min-width:0}
