@keyframes btStepIn {from{opacity:0;transform:perspective(900px) rotateY(-16deg) translateX(34px)}to{opacity:1;transform:none}}
.nifty-part-header-2 .bt-header .bt-step legend {font-family:var(--serif);font-weight:500;font-size:25px;line-height:1.15;padding:0;margin-bottom:6px}
.nifty-part-header-2 .bt-header .bt-step-p {font-size:14.5px;color:rgba(255,255,255,.74);margin-bottom:18px}
.nifty-part-header-2 .bt-header .bt-opts {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.nifty-part-header-2 .bt-header .bt-opts-3 {grid-template-columns:repeat(3,minmax(0,1fr))}
