.bt-vz .bt-vz-how h2{font-family:var(--serif);font-weight:500;font-size:clamp(34px,4.2vw,58px);line-height:1.06;margin:0 0 clamp(36px,4vw,56px)}
.bt-vz .bt-vz-how h2 em{font-style:normal;color:var(--sand)}
.bt-vz .bt-vz-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(20px,3vw,56px);counter-reset:s}
.bt-vz .bt-vz-steps li{counter-increment:s;border-top:1px solid rgba(255,255,255,.22);padding-top:24px}
.bt-vz .bt-vz-steps li::before{content:"0" counter(s);display:block;font-family:var(--serif);font-weight:500;font-size:44px;line-height:1;color:var(--sand);margin-bottom:18px}
.bt-vz .bt-vz-steps h3{font-family:var(--serif);font-weight:500;font-size:27px;line-height:1.15;margin:0 0 10px}
.bt-vz .bt-vz-steps p{font-weight:300;color:rgba(255,255,255,.78)}
.bt-vz .bt-vz-cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:clamp(36px,4vw,56px)}
.bt-vz .bt-vz-how .bt-btn{background:var(--cream);border-color:var(--cream);color:var(--ink)}
.bt-vz .bt-vz-how .bt-btn:hover{background:transparent;color:var(--cream)}
.bt-vz .bt-vz-how .bt-btn-line{background:transparent;border-color:rgba(255,255,255,.5);color:var(--cream)}
.bt-vz .bt-vz-how .bt-btn-line:hover{background:var(--cream);color:var(--ink)}

@media (max-width:1100px){
.bt-vz .bt-vz-grid{grid-template-columns:minmax(0,1fr)}
.bt-vz .bt-vz-view{position:static}
.bt-vz .bt-vz-head-in{grid-template-columns:minmax(0,1fr);align-items:start}
